 70	/**
 71	 * Generates a unique kebab-case ID from a label, appending a numeric suffix
 72	 * (-2, -3, ...) when the base ID is already taken.
 73	 *
 74	 * @param label - The human-readable label to derive an ID from.
 75	 * @param existingIds - The set of IDs already in use; the returned ID is
 76	 *   guaranteed not to be a member of this set.
 77	 * @returns A kebab-case string ID that is unique within `existingIds`.
 78	 *
 79	 * @remarks
 80	 * When `toKebabCase(label)` returns an empty string (e.g. because `label`
 81	 * consists entirely of special characters such as `"!!!"`), the function falls
 82	 * back to `"credential"` as the base ID. Suffix disambiguation (-2, -3, …)
 83	 * is still applied when needed, so labels like `"!!!"` and `"???"` resolve to
 84	 * `"credential"` and `"credential-2"` respectively.
 85	 *
 86	 * @example
 87	 * generateUniqueId('GitHub Personal', new Set())       // → 'github-personal'
 88	 * generateUniqueId('GitHub Personal', new Set(['github-personal'])) // → 'github-personal-2'
 89	 * generateUniqueId('!!!', new Set())                   // → 'credential'
 90	 */
 91	function generateUniqueId(label: string, existingIds: Set<string>): string {
 92	    const baseId = toKebabCase(label) || 'credential';
 93	    let candidateId = baseId;
 94	    let suffix = 2;
 95	    while (existingIds.has(candidateId)) {
 96	        candidateId = `${baseId}-${suffix}`;
 97	        suffix++;
 98	    }
 99	    return candidateId;
100	}

