173	 * - Duplicate `id` values within the array are rejected.
174	 *
175	 * @returns `undefined` when the field is absent or null; otherwise a
176	 *   `GitCredentialEntry[]` (possibly empty).
177	 * @throws {Error} If the value is present but structurally invalid, or if any
178	 *   entry fails validation.
179	 */
180	function parseGitCredentials(value: unknown): GitCredentialEntry[] | undefined {
181	    if (value === undefined || value === null) {
182	        return undefined;
183	    }
184	
185	    // --- New format: array of GitCredentialEntry objects ---
186	    if (Array.isArray(value)) {
187	        // Empty array is valid — treat as "no credentials".
188	        if (value.length === 0) {
189	            return [];
190	        }
191	
192	        const seenIds = new Set<string>();
193	
194	        for (let i = 0; i < value.length; i++) {
195	            const entry = value[i] as Record<string, unknown>;
196	
197	            if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
198	                throw new Error(
